import {zaloPersonalUI} from './zalo-personal-ui.js';
import {workspaceUI} from './workspace-ui.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Date(v).toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'}):'—';
const initials=s=>String(s).split(' ').filter(Boolean).slice(-2).map(x=>x[0]).join('').toUpperCase();
const roles={admin:'Quản trị viên',manager:'Trưởng nhóm',agent:'Nhân viên',viewer:'Chỉ xem'};
const statuses={open:'Đang mở',pending:'Chờ xử lý',closed:'Đã xử lý'};
let user,csrf,state={channels:[],conversations:[],users:[],replies:[],orders:[],tag_colors:[]},view='inbox',selected=null,channel='all',filter='all',contentType='chat',tagFilter='',query='',sort='recent',messages=[],events=[],note=false,polling=false,stamp='',chatStamp='',drafts=new Map(),sending=false,files=new Map(),uploading=false;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(p,method='GET',data){const r=await fetch('/api'+p,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(data===undefined?{}:{body:JSON.stringify(data)})});const d=await r.json();if(!r.ok){if(r.status===401&&user){user=null;await auth();}throw Error(d.error||'Có lỗi kết nối.');}return d;}
function show(title,html){$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="quiet" data-action="close-modal" aria-label="Đóng">×</button></div>${html}`;modal.setAttribute('aria-labelledby','dialog-title');modal.showModal();}
const field=(label,name,type='text',value='',required=true)=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="10" autocomplete="new-password"':''}>`;
function formError(f,e){let el=f.querySelector('.error');if(!el){el=document.createElement('p');el.className='error';f.append(el);}el.textContent=e.message;el.id='form-error';el.setAttribute('role','alert');for(const control of f.querySelectorAll('input,select,textarea')){control.setAttribute('aria-describedby','form-error');}}
async function auth(){const {setup,requires_setup_token}=await api('/bootstrap');app.innerHTML=`<div class="auth"><div class="auth-card"><div class="brand"><img class="brand-logo" src="/logo.png" alt="Logo Choiagency"> Choibox</div><h1>${setup?'Một nơi cho mọi cuộc trò chuyện.':'Chào mừng trở lại.'}</h1><p>${setup?'Tạo tài khoản quản trị để bắt đầu quản lý Facebook Page và Zalo OA trên máy của bạn.':'Đăng nhập để tiếp tục chăm sóc khách hàng cùng đội ngũ của bạn.'}</p><form class="form" data-form="${setup?'setup':'login'}">${setup?field('Tên của bạn','name')+(requires_setup_token?field('Khóa khởi tạo máy chủ','setup_token','password'):''):''}${field('Email','email','email')}${field('Mật khẩu'+(setup?' (ít nhất 10 ký tự)':''),'password','password')}<button class="primary">${setup?'Tạo không gian làm việc':'Đăng nhập'} →</button><p class="error" role="alert"></p></form><div class="auth-footer">Choibox 1.12.0 · Được phát triển bởi <a href="https://choiagency.top" target="_blank" rel="noopener noreferrer">Choiagency</a></div></div></div>`;}
function nav(){return `<aside class="sidebar"><div class="brand"><img class="brand-logo" src="/logo.png" alt="Logo Choiagency"><span class="brand-name">Choibox</span></div><div><div class="sectionlabel">KHÔNG GIAN LÀM VIỆC</div><nav class="nav">${[['inbox','▤','Hộp thư chung'],['reports','◷','Tổng quan'],['orders','▣','Đơn hàng'],...(user.role==='admin'?[['channels','⊞','Kênh kết nối'],['users','♧','Đội ngũ'],['replies','☷','Câu trả lời mẫu'],['audit','≡','Nhật ký'],['access','⌘','Máy chủ & truy cập']]:[])].map(([v,i,n])=>`<button data-view="${v}" class="${view===v?'active':''}" title="${n}"><span>${i}</span><span class="nav-text">${n}</span>${v==='inbox'?`<span class="count pill">${state.conversations.filter(c=>c.status!=='closed').length}</span>`:''}</button>`).join('')}</nav></div><div><div class="sectionlabel">CÁC KÊNH CỦA BẠN</div><div class="channels"><button data-channel="all" class="${channel==='all'?'active':''}"><span>⊙</span> Tất cả các kênh</button>${state.channels.map(c=>`<button data-channel="${c.id}" class="${Number(channel)===c.id?'active':''}" title="${esc(c.name)}"><span class="dot"></span>${esc(c.name)}</button>`).join('')}</div></div><div class="sidebar-bottom"><div class="userline"><div class="avatar">${esc(initials(user.name))}</div><div class="user-info"><strong>${esc(user.name)}</strong><div class="muted"><small>${roles[user.role]}</small></div></div></div><button class="quiet" data-action="password">Đổi mật khẩu</button> <button class="quiet" data-action="logout">Đăng xuất</button></div></aside>`;}
function shell(){app.innerHTML=`<div class="layout">${nav()}<main class="main"><header class="topbar"><button class="mobile-nav-toggle quiet" data-action="navigation" aria-label="Mở menu điều hướng">☰</button><div><h1>${view==='inbox'?'Hộp thư chung':{reports:'Tổng quan',orders:'Đơn hàng',channels:'Kênh kết nối',users:'Đội ngũ',replies:'Câu trả lời mẫu',audit:'Nhật ký hoạt động',access:'Máy chủ & truy cập'}[view]}</h1><p class="muted">${view==='inbox'?'Mỗi cuộc trò chuyện, một cơ hội kết nối.':'Quản lý không gian làm việc của bạn.'}</p></div><div class="flex"><span class="pill status-live"><span class="dot"></span> Không gian làm việc chung</span><button data-action="refresh" title="Làm mới" aria-label="Làm mới hộp thư">↻</button></div></header><div id="body"></div><footer class="app-footer">Choibox 1.12.0 · Được phát triển bởi <a href="https://choiagency.top" target="_blank" rel="noopener noreferrer">Choiagency</a></footer></main></div>`;renderBody();}
function empty(title,text,button=''){return `<div class="empty"><div class="empty-icon">◈</div><h2>${title}</h2><p>${text}</p>${button}</div>`;}
function current(){return state.conversations.find(c=>c.id===selected);}
function canReply(c){return c&&state.channels.find(ch=>ch.id===c.channel_id)?.can_reply;}
function filtered(){return state.conversations.filter(c=>(contentType==='all'||(c.kind||'chat')===contentType)&&(!tagFilter||tagFilter==='untagged'&&!c.tags.length||c.tags.some(t=>'tag:'+t===tagFilter))&&(channel==='all'||c.channel_id===Number(channel))&&(filter==='all'||filter==='mine'&&c.assignee===user.id||filter==='unread'&&c.unread>0||filter==='closed'&&c.status==='closed'||filter==='unassigned'&&c.assignee===null)&&(!query||[c.name,c.preview,c.channel_name,c.post_id||'',...c.tags].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>sort==='priority'?(b.priority==='high')-(a.priority==='high')||b.updated.localeCompare(a.updated):b.updated.localeCompare(a.updated));}
function listHTML(){const list=filtered();return list.length?list.map(c=>`<button class="conv ${c.id===selected?'active':''}" data-conv="${c.id}">${customerAvatar(c)}<div class="content"><div class="row"><span class="name">${esc(c.name)}</span><span class="time">${fmt(c.updated)}</span></div><div class="preview">${esc(c.preview)}</div>${c.tags.length?`<div class="list-tags">${c.tags.map(t=>tagChip(t)).join('')}</div>`:''}<div class="channel"><span class="pill ${c.provider}">${c.kind==='comment'?'f · Bình luận':c.provider==='facebook'?'f · Page':c.provider==='zalo_personal'?(c.thread_type==='group'?'Z · Nhóm':'Z · Cá nhân'):'Z · OA'}</span><span>${c.priority==='high'?'⚑ ':''}${esc(c.channel_name.split(' • ')[0])}</span>${c.unread?`<span class="unread">${c.unread}</span>`:''}</div></div></button>`).join(''):empty('Hộp thư đang trống','Hội thoại từ những kênh bạn được cấp quyền sẽ xuất hiện tại đây.',user.role==='admin'&&!state.channels.length?'<button class="primary" data-action="demo">Khám phá với dữ liệu mẫu</button><button data-view="channels">Kết nối kênh thật</button>':'');}
function tagOptions(){const tags=[...new Set(state.conversations.filter(c=>(c.kind||'chat')===contentType&&(channel==='all'||c.channel_id===Number(channel))).flatMap(c=>c.tags))].sort((a,b)=>a.localeCompare(b,'vi'));return [['','Tất cả'],['untagged','Chưa có thẻ'],...tags.map(t=>['tag:'+t,t])].map(([v,n])=>`<button type="button" data-tag-filter="${esc(v)}" aria-pressed="${tagFilter===v}" class="tag-choice ${tagFilter===v?'selected':''}" ${v.startsWith('tag:')?`style="--tag-color:${tagColor(n)}"`:''}>${v.startsWith('tag:')?'<span class="tag-dot"></span>':''}${esc(n)}</button>`).join('');}
function inbox(){return `<div class="workspace ${selected?'selected':''}"><section class="inbox"><div class="inbox-controls"><div class="content-tabs" role="tablist" aria-label="Tin nhắn và bình luận">${[['chat','Tin nhắn'],['comment','Bình luận']].map(([v,n])=>`<button type="button" role="tab" id="tab-${v}" data-content-tab="${v}" aria-selected="${contentType===v}" aria-controls="conv-list" tabindex="${contentType===v?0:-1}">${n}</button>`).join('')}</div><input class="search" id="search" type="search" placeholder="Tìm khách hàng, tin nhắn, thẻ…" aria-label="Tìm hội thoại" value="${esc(query)}"><div class="filter-row">${[['all','Tất cả'],['mine','Của tôi'],['unread','Chưa đọc']].map(([v,n])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${n}</button>`).join('')}<select id="other-filter" aria-label="Bộ lọc khác"><option value="">Khác</option><option value="unassigned" ${filter==='unassigned'?'selected':''}>Chưa giao</option><option value="closed" ${filter==='closed'?'selected':''}>Đã xử lý</option></select></div><div class="tag-filter"><span class="muted">Lọc theo thẻ</span><div id="tag-filter" class="tag-choices" role="group" aria-label="Lọc theo thẻ khách hàng">${tagOptions()}</div></div><div class="filter-row"><select id="sort" aria-label="Sắp xếp"><option value="recent">Mới nhất</option><option value="priority" ${sort==='priority'?'selected':''}>Ưu tiên trước</option></select><small class="muted" id="result-count">${filtered().length} hội thoại</small></div></div><div class="list" id="conv-list" role="tabpanel" aria-labelledby="tab-${contentType}">${listHTML()}</div></section><section class="chat" id="chat">${chatHTML()}</section><aside class="detail" id="detail">${detailHTML()}</aside></div>`;}
function chatHTML(){const c=current();if(!c)return empty('Cùng khách hàng, từ một nơi.','Chọn một hội thoại để xem lịch sử, phối hợp cùng nhân viên và trả lời khách.');const reply=canReply(c),draft=drafts.get(c.id)||'';return `<div class="chat-head"><div class="flex"><button class="quiet mobile-back" data-action="back" aria-label="Quay lại">←</button>${customerAvatar(c)}<div><h3>${esc(c.name)}</h3><div class="sub">${c.thread_type==='group'?'Nhóm Zalo · ':''}${esc(c.channel_name)} · ${statuses[c.status]}</div></div></div><div class="flex"><button data-action="edit-conversation" title="Thông tin hội thoại" aria-label="Thông tin hội thoại">⋯</button>${reply?`<button data-action="resolve">${c.status==='closed'?'Mở lại':'✓ Đã xử lý'}</button>`:''}</div></div>${c.kind==='comment'?`<div class="notice">${c.deleted?'Bình luận gốc đã bị xóa.':'Trả lời tại đây sẽ được đăng công khai dưới bình luận.'} <a href="https://www.facebook.com/${encodeURIComponent(c.post_id)}" target="_blank" rel="noopener noreferrer">Mở bài viết ↗</a></div>`:''}${c.kind!=='comment'&&reply&&c.provider==='facebook'?`<div class="actions history-actions">${c.provider==='facebook'?`<button data-history-conversation="${c.id}">Tải tin nhắn cũ hơn</button><a href="https://business.facebook.com/latest/inbox/all?asset_id=${encodeURIComponent(state.channels.find(ch=>ch.id===c.channel_id)?.external_id||'')}" target="_blank" rel="noopener noreferrer">Mở hộp thư Facebook ↗</a>`:''}</div>`:''}<div class="messages" id="messages">${messagesHTML()}</div><form class="composer" data-form="compose" data-conversation="${c.id}"><div class="composer-tabs"><button type="button" data-compose="reply" class="${!note?'active':''}">Trả lời</button><button type="button" data-compose="note" class="${note?'active':''}">Ghi chú nội bộ</button><select id="quick-reply" aria-label="Câu trả lời mẫu" ${!reply?'disabled':''}><option value="">Câu trả lời mẫu ↗</option>${state.replies.map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('')}</select></div><textarea name="text" id="compose-text" aria-describedby="compose-help" aria-label="${note?'Ghi chú nội bộ':'Tin nhắn trả lời'}" placeholder="${reply?(note?'Chỉ đội ngũ của bạn nhìn thấy ghi chú này…':'Nhập câu trả lời…'):'Bạn chỉ có quyền xem kênh này.'}" maxlength="${note?5000:2000}" ${!reply||!state.channels.find(ch=>ch.id===c.channel_id)?.enabled?'disabled':''}>${esc(draft)}</textarea>${filePreview(c.id)}<small id="compose-help" class="muted">Enter để gửi · Shift+Enter xuống dòng${!note&&c.kind!=='comment'?`<span class="attachment-limits">${c.provider==='zalo'?'Zalo: ảnh JPG/PNG ≤ 1 MB · PDF/DOC/DOCX/CSV ≤ 5 MB':'Ảnh, video và tệp ≤ 25 MB mỗi tin'}</span>`:''}</small><div class="composer-tools">${reply&&c.kind!=='comment'?`<button type="button" data-action="attach" ${note||sending||uploading?'disabled':''}>${icon('clip')} Đính kèm</button><input id="attachment-file" type="file" hidden accept="${c.provider==='zalo'?'.jpg,.jpeg,.png,.pdf,.doc,.docx,.csv':'.jpg,.jpeg,.png,.gif,.webp,.mp4,.mov,.webm,.mp3,.wav,.pdf,.txt,.csv,.doc,.docx,.xls,.xlsx,.pptx,.zip'}">`:""}${reply?`<button type="button" data-action="create-order">${icon('box')} Tạo đơn hàng</button>`:""}<span class="muted">${uploading?'Đang tải tệp…':''}</span></div><div class="composer-bottom"><small class="muted">${note?'Ghi chú không gửi cho khách':c.mode==='demo'?'Dữ liệu mẫu · Không gửi ra nền tảng':!state.channels.find(ch=>ch.id===c.channel_id)?.verified?'Cần quản trị viên kiểm tra kết nối trước khi gửi':c.kind==='comment'?'Bình luận công khai bằng danh tính Page':'Gửi qua '+(c.provider==='facebook'?'Facebook Messenger':c.provider==='zalo_personal'?'Zalo cá nhân':'Zalo OA')}</small><button class="primary" ${!reply||sending||(!note&&c.deleted)?'disabled':''}>${note?'Lưu ghi chú':c.kind==='comment'?'Đăng trả lời':'Gửi tin nhắn'} ↗</button></div></form>`;}
let pendingConfirmation=null;
function confirmAction(title,text,button,run){pendingConfirmation=run;show(title,`<p class="help">${esc(text)}</p><form class="form" data-form="confirm-action"><div class="actions"><button type="button" data-action="close-modal">Huỷ</button><button type="submit" class="primary danger">${esc(button)}</button></div><p class="error" role="alert"></p></form>`);}
function messageActions(m,c){if(!canReply(c)||['sending','deleted'].includes(m.status))return '';const remote=c.kind==='comment'&&m.kind!=='note'&&m.external_id;return `<details class="message-menu"><summary aria-label="Tuỳ chọn tin nhắn" title="Tuỳ chọn tin nhắn">⋯</summary><div class="message-menu-panel">${remote?`<button type="button" data-moderate="${m.hidden?'unhide':'hide'}" data-message-id="${m.id}">${m.hidden?'Hiện bình luận':'Ẩn bình luận'}</button><button type="button" data-moderate="delete" data-message-id="${m.id}">Xoá bình luận</button>`:`<button type="button" data-moderate="local-delete" data-message-id="${m.id}">Xoá tin nhắn</button>`}</div></details>`;}
function messageAvatar(m,c,name){if(m.kind==='incoming'&&c.thread_type!=='group')return customerAvatar(c);return `<div class="avatar customer-avatar sender-avatar"><span>${esc(initials(name))}</span>${c.provider==='zalo_personal'&&c.thread_type==='group'&&m.author_id?`<img src="/api/messages/${m.id}/avatar" alt="Ảnh đại diện ${esc(name)}" loading="lazy" referrerpolicy="no-referrer">`:''}</div>`;}
function messagesHTML(){const c=current();return `<div class="date-divider">${c?.mode==='demo'?'HỘI THOẠI THỬ NGHIỆM':'LỊCH SỬ HỘI THOẠI'}</div>${messages.map(m=>{const internal=['note','order'].includes(m.kind),name=m.sender_name||m.author_name||(m.kind==='outgoing'?c.channel_name:c.thread_type==='group'?'Thành viên nhóm':c.name);return `<article class="message ${m.kind} ${m.status}" title="${esc(m.error||'')}">${!internal?messageAvatar(m,c,name):''}<div class="message-content"><div class="message-author">${m.kind==='order'?'Đơn hàng nội bộ · ':m.kind==='note'?'Ghi chú · ':''}${esc(name)}</div><div class="message-body"><div class="bubble">${m.kind==='order'?orderCard(m.order_id):m.attachment?attachmentHTML(m.attachment,c?.provider==='zalo_personal'&&m.body.startsWith('[Sticker]')):esc(m.body)}</div>${messageActions(m,c)}</div><div class="message-meta">${m.hidden?'<span>Đã ẩn trên Facebook</span>':''}<span>${fmt(m.created)}</span>${m.kind==='outgoing'?`<span>${{sent:'',demo:'✓ Gửi thử',failed:'⚠ Chưa xác nhận gửi',sending:'Đang gửi…',read:'✓✓ Đã xem'}[m.status]??esc(m.status)}</span>`:''}</div>${m.error?`<p class="error">${esc(m.error)}</p>`:''}</div></article>`;}).join('')}`;}
function closeMessageMenus(restore=false){document.querySelectorAll('.message-menu[open]').forEach(d=>{d.open=false;if(restore)d.querySelector('summary').focus();});}
document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches?.('.message-menu')||!d.open)return;const panel=d.querySelector('.message-menu-panel'),box=d.closest('.messages').getBoundingClientRect();d.classList.remove('menu-below','menu-start','menu-end');let r=panel.getBoundingClientRect();if(r.top<box.top+4)d.classList.add('menu-below');if(r.left<box.left+4)d.classList.add('menu-start');else if(r.right>box.right-4)d.classList.add('menu-end');},true);
document.addEventListener('click',e=>{const menu=e.target.closest('.message-menu');document.querySelectorAll('.message-menu[open]').forEach(d=>{if(d!==menu||e.target.closest('button'))d.open=false;});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.message-menu[open]')){e.preventDefault();closeMessageMenus(true);}});
function detailHTML(){const c=current();if(!c)return '';const editable=canReply(c),manage=['admin','manager'].includes(user.role);return `${customerProfile(c,editable)}${editable&&c.kind!=='comment'?`<button class="delete-conversation" data-delete-conversation="${c.id}">Xoá cuộc chat khỏi Choibox</button>`:''}<div class="detail-section"><h3>THÔNG TIN HỘI THOẠI</h3><label>Người phụ trách</label><select id="assignee" aria-label="Người phụ trách" ${!editable||!manage?'disabled':''}><option value="">Chưa phân công</option>${state.users.filter(u=>u.role!=='viewer').map(u=>`<option value="${u.id}" ${c.assignee===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select>${editable&&!c.assignee?'<button class="quiet" data-action="claim">+ Nhận hội thoại</button>':''}<label>Trạng thái</label><select id="status" aria-label="Trạng thái" ${!editable?'disabled':''}>${Object.entries(statuses).map(([v,n])=>`<option value="${v}" ${c.status===v?'selected':''}>${n}</option>`).join('')}</select><label>Ưu tiên</label><select id="priority" aria-label="Ưu tiên" ${!editable?'disabled':''}><option value="normal" ${c.priority==='normal'?'selected':''}>Bình thường</option><option value="high" ${c.priority==='high'?'selected':''}>Cao</option></select></div><div class="detail-section"><div class="section-heading"><h3>THẺ KHÁCH HÀNG</h3></div><div class="customer-tags">${c.tags.map(t=>tagChip(t,editable)).join('')||'<small class="muted">Chưa có thẻ</small>'}</div>${editable?'<button class="add-tag" data-action="add-tag">+ Thêm thẻ</button>':''}</div><div class="detail-section"><div class="section-heading"><h3>ĐƠN HÀNG</h3>${editable?'<button class="quiet" data-action="create-order" aria-label="Tạo đơn hàng">+</button>':''}</div>${(state.orders||[]).filter(o=>o.conversation_id===c.id).map(o=>orderSummary(o,editable)).join('')||'<p class="muted"><small>Chưa có đơn hàng. Tạo đơn ngay trong cuộc chat này.</small></p>'}</div><div class="detail-section"><h3>LỊCH SỬ XỬ LÝ</h3>${events.slice(0,8).map(e=>`<div class="event">${esc(e.user_name||'Hệ thống')} · ${esc(e.action)}<br><small>${fmt(e.created)}</small></div>`).join('')||'<small class="muted">Chưa có hoạt động</small>'}</div>`;}
function refreshList(){const co=current();if(co){const h=$('.chat-head h3'),a=$('.chat-head .avatar');if(h)h.textContent=co.name;if(a)a.outerHTML=customerAvatar(co);}if($('#conv-list')){$('#conv-list').innerHTML=listHTML();$('#result-count').textContent=filtered().length+' hội thoại';if($('#tag-filter')&&document.activeElement!==$('#tag-filter'))$('#tag-filter').innerHTML=tagOptions();}}
function recoveryHTML(c){if(c.provider!=='zalo_personal'||!c.recovery?.length)return '';const busy=c.recovery.some(r=>r.status==='scanning'),partial=c.recovery.some(r=>r.status!=='reached');return `<div class="recovery-status" role="status">${c.recovery.map(r=>`<p><strong>${esc(r.label)}</strong> · ${esc(r.message)}<br><small>Rà từ ${fmt(r.gap_from)} · ${r.pages} trang · ${r.imported} tin mới lưu</small></p>`).join('')}<button data-recover-zalo="${c.id}" data-recovery-restart="${partial?0:1}" ${busy||!c.enabled?'disabled':''}>${busy?'Đang rà lịch sử…':partial?'Tiếp tục rà tin thiếu':'Rà lại tin Zalo'}</button><small class="muted">Phạm vi lịch sử phụ thuộc dữ liệu Zalo trả về.</small></div>`;}
function renderBody(){const b=$('#body');b.className=view==='inbox'?'main':'page';if(view==='inbox'){b.innerHTML=inbox();scrollChat();return;}if(view==='orders'){b.innerHTML=ordersPage();return;}if(view==='reports'){const live=state.conversations.filter(c=>c.mode==='live'),demo=state.conversations.filter(c=>c.mode==='demo');b.innerHTML=`<div class="page-intro"><div><h2>Nhìn rõ công việc hôm nay.</h2><p>Tổng hợp các hội thoại thuộc kênh bạn được cấp quyền.</p></div></div>${demo.length?'<div class="notice">Dữ liệu mẫu đang được bật. Các chỉ số dưới đây chỉ tính hội thoại từ kênh thật.</div>':''}<div class="cards">${[['Tổng hội thoại',live.length,'Toàn bộ hội thoại đã nhận'],['Đang mở',live.filter(c=>c.status==='open').length,'Cần phản hồi hoặc tiếp tục xử lý'],['Chờ xử lý',live.filter(c=>c.status==='pending').length,'Đang chờ thông tin hoặc phối hợp'],['Đã xử lý',live.filter(c=>c.status==='closed').length,'Hội thoại được đánh dấu hoàn tất']].map(([t,n,s])=>`<div class="card"><small class="muted">${t}</small><div class="big">${n}</div><div class="metric-sub">${s}</div></div>`).join('')}</div><h3 class="detail-section">Theo người phụ trách</h3><div class="table-wrap"><table><thead><tr><th>Nhân viên</th><th>Đang xử lý</th><th>Đã xử lý</th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${live.filter(c=>c.assignee===u.id&&c.status!=='closed').length}</td><td>${live.filter(c=>c.assignee===u.id&&c.status==='closed').length}</td></tr>`).join('')}</tbody></table></div>`;return;}
 if(view==='channels'){b.innerHTML=`<div class="page-intro"><div><h2>Kết nối, cùng một hộp thư.</h2><p>Quản lý Facebook Page, Zalo cá nhân và Zalo Official Account.</p></div><button class="primary" data-action="add-channel">+ Thêm kênh</button></div><div class="notice">Quản trị viên kết nối Page hoặc tài khoản Zalo một lần. Nhân viên dùng chung các kênh được cấp quyền. Với Facebook, đăng nhập và chọn Page để kết nối. Đồng bộ lịch sử mỗi lượt tối đa 5 cuộc chat, 50 tin mỗi cuộc; bấm tiếp để tải thêm cuộc chat. Trong từng cuộc chat, chọn Tải tin nhắn cũ hơn để tải tiếp. Zalo cá nhân hỗ trợ chat 1-1, hội thoại nhóm và tự tải phần tin gần đây Zalo trả về.</div><div class="cards">${state.channels.map(c=>`<div class="card"><span class="pill ${c.provider}">${c.provider==='facebook'?'Facebook Page':c.provider==='zalo_personal'?'Zalo cá nhân':'Zalo OA'}</span> ${c.mode==='demo'?'<span class="pill demo">Thử nghiệm</span>':''}<h3>${esc(c.name)}</h3><p>${c.enabled?'Đang bật':'Tạm dừng'} · ${esc(c.health)}<br>Nhận sự kiện gần nhất: ${fmt(c.last_event)}</p>${recoveryHTML(c)}<div class="actions">${c.provider==='facebook'&&c.mode==='live'?`<button data-history-channel="${c.id}">Đồng bộ tin nhắn cũ</button>`:''}<button data-check-channel="${c.id}">Kiểm tra kết nối</button>${c.mode==='live'?`<button data-credentials="${c.id}">${c.provider==='facebook'?'Kết nối lại Facebook':c.provider==='zalo_personal'?'Kết nối lại Zalo':'Cập nhật OA'}</button>`:''}<button data-toggle-channel="${c.id}">${c.enabled?'Tạm dừng':'Bật lại'}</button><button class="danger-text" data-delete-channel="${c.id}">Xoá kênh</button></div></div>`).join('')||empty('Thêm kênh đầu tiên','Kết nối Facebook Page hoặc Zalo OA để bắt đầu.')}</div><p class="help"><button data-action="facebook-setup">Cấu hình Facebook · dành cho người triển khai</button></p><p class="help">${!state.channels.some(c=>c.mode==='demo')?'<button data-action="demo">Tạo dữ liệu mẫu để dùng thử</button>':''}</p>`;return;}
 if(view==='access')loadAccess();if(view==='users')loadUsers();if(view==='audit')loadAudit();if(view==='replies')b.innerHTML=`<div class="page-intro"><div><h2>Phản hồi nhanh, nhất quán.</h2><p>Các mẫu dùng chung cho đội ngũ.</p></div><button class="primary" data-action="add-reply">+ Thêm mẫu</button></div><div class="cards">${state.replies.map(r=>`<div class="card"><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p></div>`).join('')}</div>`;
}
async function loadAccess(){const data=await api('/access');if(view!=='access')return;loadAccess.cache=data;$('#body').innerHTML=`<div class="page-intro"><div><h2>Một máy chủ. Cả đội cùng làm việc.</h2><p>Bạn kết nối Page/OA một lần; nhân viên chỉ cần tài khoản được cấp.</p></div></div><div class="notice">Choibox có một tài khoản quản trị cho mỗi không gian làm việc. Tạo người dùng tại Đội ngũ và cấp quyền xem/trả lời cho các kênh. Nhân viên đăng nhập vào cùng địa chỉ dưới đây; không cần nhập token Facebook hoặc Zalo.</div><div class="cards"><div class="card"><h3>Địa chỉ đăng nhập dùng chung</h3>${data.login_urls.length?data.login_urls.map(url=>`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a></p>`).join(''):'<p>Chưa cấu hình địa chỉ máy chủ công khai.</p>'}<p class="help">${data.public_url?'Địa chỉ HTTPS dùng cho nhân viên ở mọi nơi.':'Các địa chỉ LAN chỉ dùng được trong cùng mạng. Để truy cập từ Internet, triển khai gói máy chủ HTTPS và đặt PUBLIC_URL.'}</p><button data-action="export-connection">Tải cấu hình cho máy nhân viên</button></div><div class="card"><h3>Quy trình cho nhân viên</h3><p>1. Mở Choibox trên macOS hoặc Windows.<br>2. Dùng địa chỉ máy chủ / file cấu hình do quản trị viên cung cấp.<br>3. Đăng nhập bằng tài khoản được cấp.<br>4. Các hội thoại thuộc kênh được cấp quyền xuất hiện ngay.</p></div></div><div class="card storage-card" id="storage-card" aria-live="polite">Đang tải thiết lập lưu trữ…</div>`;await loadStorage();}
async function loadStorage(){try{const d=await api('/storage');if(view==='access'&&$('#storage-card'))$('#storage-card').innerHTML=storageHTML(d);}catch(e){if(view==='access'&&$('#storage-card'))$('#storage-card').innerHTML='<p role="alert">'+esc(e.message)+'</p><button data-action="storage-retry">Thử lại</button>';}}
async function loadUsers(){const users=await api('/users');if(view!=='users')return;$('#body').innerHTML=`<div class="page-intro"><div><h2>Đúng người, đúng quyền.</h2><p>Cấp quyền xem hoặc trả lời riêng cho từng Page / OA.</p></div><button class="primary" data-action="add-user">+ Thêm người dùng</button></div><div class="table-wrap"><table><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Kênh được cấp</th><th>Trạng thái</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><br><small class="muted">${esc(u.email)}</small></td><td>${roles[u.role]}</td><td>${u.role==='admin'?'Mọi kênh':u.grants.length+' kênh'}</td><td>${u.active?'Hoạt động':'Đã khóa'}</td><td><button data-edit-user="${u.id}">Phân quyền</button></td></tr>`).join('')}</tbody></table></div><div class="help">Quản trị viên: quản lý toàn bộ. Trưởng nhóm: phân công trong kênh có quyền trả lời. Nhân viên: nhận hội thoại chưa giao, trả lời và cập nhật trong kênh được cấp. Chỉ xem: đọc hội thoại, không thay đổi dữ liệu.</div>`;loadUsers.cache=users;}
async function loadAudit(){const a=await api('/audit');if(view!=='audit')return;$('#body').innerHTML=`<div class="page-intro"><div><h2>Mọi thay đổi đều có dấu vết.</h2><p>300 hoạt động gần nhất trong không gian làm việc.</p></div></div><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Người dùng</th><th>Hoạt động</th><th>Chi tiết</th></tr></thead><tbody>${a.map(e=>`<tr><td>${fmt(e.created)}</td><td>${esc(e.user_name||'Hệ thống')}</td><td>${esc(e.action)}</td><td>${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div>`;}
function refreshCustomerHeader(){const c=current(),el=$('.chat-head .customer-avatar');if(!c||!el)return;if(el.dataset.profileStamp!==`${Number(c.avatar_updated)||0}:${c.name}`)el.outerHTML=customerAvatar(c);const name=$('.chat-head h3');if(name)name.textContent=c.name;}
let chatAtBottom=true;
document.addEventListener("scroll",e=>{const m=e.target;if(m.id==="messages")chatAtBottom=m.scrollHeight-m.scrollTop-m.clientHeight<80;},true);
document.addEventListener("load",e=>{if(e.target.matches?.(".messages img")&&chatAtBottom)scrollChat();},true);
function scrollChat(){chatAtBottom=true;const m=$('#messages');if(m)m.scrollTop=m.scrollHeight;}
async function reload(full=false){state=await api('/state');if(selected&&!current()){selected=null;messages=[];}if(full)shell();else if(view==='inbox'){refreshList();if(current()){$('#detail').innerHTML=detailHTML();refreshCustomerHeader();}}stamp=JSON.stringify(state);}
async function choose(id){selected=id;note=false;messages=await api(`/conversations/${id}/messages`);events=await api(`/conversations/${id}/audit`);await api(`/conversations/${id}/read`,'POST',{});await reload();if(view==='inbox'){$('#body').innerHTML=inbox();scrollChat();}chatStamp=JSON.stringify(messages);}
async function patch(data){const c=current();await api('/conversations/'+c.id,'PATCH',{version:c.version,...data});await reload();events=await api(`/conversations/${c.id}/audit`);if(view==='inbox'){$('#chat').innerHTML=chatHTML();$('#detail').innerHTML=detailHTML();refreshCustomerHeader();scrollChat();}}
let facebookFlow=null,facebookTimer=null;
function stopFacebook(){clearInterval(facebookTimer);facebookTimer=null;facebookFlow=null;}
async function addChannel(){
 show('Thêm kênh',`<div class="connection-options"><button class="connection-option" data-action="connect-facebook"><strong>f · Kết nối Facebook</strong><span>Đăng nhập Facebook, chọn Page. Choibox tự lấy thông tin kết nối.</span></button><button class="connection-option" data-action="connect-zalo-personal"><strong>Z · Zalo cá nhân</strong><span>Quét mã QR bằng điện thoại. Không cần App ID hay token.</span></button><button class="connection-option" data-action="connect-zalo"><strong>Z · Zalo Official Account</strong><span>Kết nối OA bằng thông tin ứng dụng Zalo.</span></button></div><p class="help">Chỉ quản trị viên kết nối kênh. Nhân viên sử dụng các kênh được cấp quyền.</p>`);
}
async function facebookSetup(){
 const c=await api('/facebook/config');
 if(c.shared){show('Kết nối Facebook của Choibox',`<p>Máy này sử dụng ứng dụng Meta chung của Choibox. Bạn chỉ cần đăng nhập Facebook và chọn Page.</p><p role="status">${esc(c.error||'Đã kích hoạt kết nối chung.')}</p><button class="primary" data-action="connect-facebook">Kết nối Facebook</button>`);return;}
 show('Cấu hình Facebook cho Choibox',`<p class="help">Thiết lập một lần bởi người triển khai Choibox. Sau đó người thêm kênh chỉ đăng nhập Facebook và chọn Page.</p><form class="form" data-form="facebook-config">${field('Meta App ID của Choibox','app_id','text',c.app_id)}${field(c.configured?'App Secret mới (để trống để giữ nguyên)':'App Secret','app_secret','password','',!c.configured)}${field('Facebook Login for Business Configuration ID (nếu sử dụng)','config_id','text',c.config_id,false)}${field('Graph API version','graph_version','text',c.graph_version)}<p class="help">Nhập thông tin của ứng dụng Meta riêng dành cho Choibox. App Secret được mã hóa trên máy chủ.</p><button class="primary">Lưu cấu hình</button><p class="error" role="alert"></p></form><div class="connection-technical"><h3>Địa chỉ khai báo trên Meta</h3>${c.redirect_uri?`<p>Valid OAuth Redirect URI:<br><code>${esc(c.redirect_uri)}</code></p><p>Webhook Callback URL:<br><code>${esc(c.webhook_url)}</code></p>`:'<p>Chưa có địa chỉ HTTPS. Thiết lập địa chỉ máy chủ trong Choibox trước khi đăng nhập Facebook.</p>'}${c.verify_token?`<p>Webhook Verify Token:<br><code>${esc(c.verify_token)}</code></p>`:'<p>Lưu cấu hình để Choibox tạo Verify Token tự động.</p>'}${c.temporary_url?'<p class="help">Đường dẫn hiện tại là tunnel tạm. Khi đường dẫn thay đổi, cần cập nhật hai địa chỉ trên Meta. Nên dùng tên miền cố định.</p>':''}<p class="help">Ứng dụng cần Facebook Login, quyền Page/tin nhắn/bình luận và webhook Page gồm messages, messaging_postbacks, message_deliveries, message_reads, feed. Quyền sử dụng cho tài khoản bên ngoài cần được Meta phê duyệt.</p></div>`);
 for(const el of modal.querySelectorAll('input[type=password]'))el.removeAttribute('minlength');
}
async function facebookStart(){
 stopFacebook();const config=await api('/facebook/config');
 if(!config.ready){show('Facebook chưa sẵn sàng',`<p class="help">Người triển khai cần ${!config.configured?'cấu hình ứng dụng Meta dành cho Choibox':'thiết lập địa chỉ HTTPS cho máy chủ'} một lần trước khi sử dụng đăng nhập Facebook. Sau khi hoàn tất, bạn chỉ cần đăng nhập và chọn Page.</p><button class="primary" data-action="facebook-setup">Cấu hình dành cho người triển khai</button>`);return;}
 const flow=await api('/facebook/start','POST',{});facebookFlow=flow.id;
 show('Đăng nhập Facebook',`<p class="help" role="status">Hoàn tất đăng nhập và cấp quyền trong trình duyệt. Danh sách Page sẽ tự xuất hiện tại đây.</p><a class="facebook-login" href="${esc(flow.url)}" target="_blank" rel="noopener noreferrer">Mở Facebook để đăng nhập ↗</a><p class="help">Có thể kết nối thêm tài khoản khác bằng cách bắt đầu lại và chọn tài khoản trong Facebook.</p>`);
 window.open(flow.url,'_blank','noopener,noreferrer');
 let busy=false;facebookTimer=setInterval(async()=>{if(busy||!modal.open||facebookFlow!==flow.id)return;busy=true;try{const result=await api('/facebook/flows/'+flow.id);if(facebookFlow!==flow.id)return;
  if(result.status==='failed'){clearInterval(facebookTimer);show('Chưa kết nối được Facebook',`<p class="error" role="alert">${esc(result.error)}</p><button class="primary" data-action="connect-facebook">Thử lại</button>`);}
  if(result.status==='ready'){clearInterval(facebookTimer);show('Chọn Page để kết nối',result.pages.length?`<form class="form" data-form="facebook-pages"><p class="help">Chọn các Page muốn dùng chung trong Choibox. Page đã kết nối sẽ được cập nhật quyền truy cập.</p><div class="page-choices">${result.pages.map(p=>`<label class="page-choice"><input type="checkbox" name="page" value="${esc(p.id)}"><span><strong>${esc(p.name)}</strong>${p.connected?'<small>Đã kết nối · Chọn để cập nhật</small>':''}</span></label>`).join('')}</div><button class="primary">Kết nối Page đã chọn</button><p class="error" role="alert"></p></form>`:`<p class="help">Facebook chưa trả về Page nào. Kiểm tra tài khoản đang đăng nhập có quyền quản lý Page và đã cấp quyền cho Choibox.</p><button data-action="connect-facebook">Đăng nhập lại</button>`);}
 }catch(e){clearInterval(facebookTimer);if(facebookFlow===flow.id)show('Phiên kết nối đã kết thúc',`<p class="error" role="alert">${esc(e.message)}</p><button data-action="connect-facebook">Kết nối lại</button>`);}finally{busy=false;}},2000);
}
modal.addEventListener('close',()=>{const id=facebookFlow;stopFacebook();if(id)api('/facebook/flows/'+id,'DELETE').catch(()=>{});});

function channelForm(id){const c=id?state.channels.find(x=>x.id===id):null;show(c?'Cập nhật Zalo OA':'Kết nối Zalo OA',`<form class="form" data-form="channel" data-id="${id||''}"><input type="hidden" name="provider" value="zalo">${!c?field('Tên hiển thị','name')+field('Zalo OA ID','external_id'):''}${field('Access Token'+(c?' (để trống để giữ nguyên)':''),'access_token','password','',!c)}${field('OA Secret Key'+(c?' (để trống để giữ nguyên)':''),'app_secret','password','',!c)}${field('Zalo App ID'+(c?' (để trống để giữ nguyên)':''),'app_id','text','',!c)}<p class="help">Zalo OA hiện dùng cấu hình ứng dụng Zalo. Luồng đăng nhập và chọn kênh tự động trong bản này áp dụng cho Facebook.</p><button class="primary">${c?'Lưu cấu hình':'Kết nối OA'}</button><p class="error" role="alert"></p></form>`);for(const i of modal.querySelectorAll('input[type=password]'))i.removeAttribute('minlength');}
function userForm(id){const u=id?loadUsers.cache.find(x=>x.id===id):null;show(u?'Phân quyền · '+u.name:'Thêm người dùng',`<form class="form" data-form="user" data-id="${id||''}">${!u?field('Họ tên','name')+field('Email','email','email'):''}${field(u?'Mật khẩu mới (để trống nếu giữ nguyên)':'Mật khẩu (ít nhất 10 ký tự)','password','password','',!u)}<label>Vai trò</label><select name="role" aria-label="Vai trò">${Object.entries(roles).filter(([v])=>v!=='admin'||u?.role==='admin').map(([v,n])=>`<option value="${v}" ${(u?.role||'agent')===v?'selected':''}>${n}</option>`).join('')}</select>${u?`<label>Trạng thái</label><select name="active" aria-label="Trạng thái tài khoản"><option value="1" ${u.active?'selected':''}>Hoạt động</option><option value="0" ${!u.active?'selected':''}>Khóa tài khoản</option></select>`:''}<label>Quyền theo kênh</label>${state.channels.map(c=>{const g=u?.grants.find(x=>x.channel_id===c.id);return `<div class="grant"><input type="checkbox" name="grant-${c.id}" id="grant-${c.id}" ${g?'checked':''}><label for="grant-${c.id}">${esc(c.name)}</label><select name="reply-${c.id}" aria-label="Quyền cho ${esc(c.name)}"><option value="0">Chỉ xem</option><option value="1" ${g?.can_reply?'selected':''}>Xem & trả lời</option></select></div>`;}).join('')}<p class="help">Vai trò quản trị tự có quyền mọi kênh. Vai trò chỉ xem luôn bị chặn trả lời dù kênh được chọn quyền trả lời.</p><button class="primary">Lưu người dùng</button><p class="error"></p></form>`);}
app.addEventListener('keydown',e=>{if(!e.target.dataset.contentTab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?'chat':e.key==='End'?'comment':contentType==='chat'?'comment':'chat';$('#tab-'+next).click();});
app.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;refreshList();}if(e.target.id==='compose-text')drafts.set(selected,e.target.value);});
app.addEventListener('keydown',e=>{if(e.target.id!=='compose-text'||e.key!=='Enter'||e.shiftKey||e.isComposing||e.keyCode===229||e.repeat)return;e.preventDefault();const button=e.target.form?.querySelector('button.primary');if(!sending&&!e.target.disabled&&button&&!button.disabled&&(e.target.value.trim()||files.has(selected)))e.target.form.requestSubmit(button);});
app.addEventListener('change',async e=>{try{const t=e.target;if(t.id==='other-filter'){filter=t.value||'all';renderBody();}if(t.id==='sort'){sort=t.value;refreshList();}if(['assignee','status','priority'].includes(t.id))await patch({[t.id]:t.id==='assignee'?(t.value?Number(t.value):null):t.value});if(t.id==='quick-reply'){const r=state.replies.find(r=>r.id===Number(t.value));if(r){$('#compose-text').value=r.body;drafts.set(selected,r.body);t.value='';}}}catch(e){toast(e.message);await reload(true);}});
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if((sending||uploading)&&(t.dataset.conv||t.dataset.channel||t.dataset.view||t.dataset.compose||t.dataset.action==='refresh'||t.dataset.action==='back'||t.dataset.action==='logout'||t.dataset.contentTab))return;try{
 if(t.dataset.storageAction){const action=t.dataset.storageAction;confirmAction(action==='compact'?'Thu gọn cơ sở dữ liệu':'Dọn tệp đến hạn',action==='compact'?'Choibox có thể tạm chậm trong lúc thu gọn. Không xoá tin nhắn hoặc đơn hàng. Nên thực hiện lúc ít người dùng.':'Chỉ dọn tệp đã hết thời gian lưu hoặc vượt giới hạn. Tệp không có nguồn tải lại có thể không xem lại được; tin nhắn chữ và đơn hàng vẫn giữ.',action==='compact'?'Thu gọn':'Dọn tệp',async()=>{await api('/storage/'+action,'POST',{confirm:true});await loadStorage();toast('Đã hoàn tất.');});}
 if(t.dataset.deleteConversation){const id=Number(t.dataset.deleteConversation);confirmAction('Xoá cuộc chat khỏi Choibox','Xoá nội dung cuộc chat cho toàn đội ngũ. Nền tảng gốc vẫn giữ cuộc chat. Tin mới từ khách sẽ mở lại cuộc chat. Không thể hoàn tác.','Xoá cuộc chat',async()=>{await api('/conversations/'+id,'DELETE',{confirm:true});drafts.delete(id);selected=null;messages=[];await reload(true);});}
 if(t.dataset.historyChannel||t.dataset.historyConversation){t.disabled=true;const old=t.textContent;t.textContent='Đang tải lịch sử…';try{const id=t.dataset.historyChannel||t.dataset.historyConversation;const r=await api('/'+(t.dataset.historyChannel?'channels':'conversations')+'/'+id+'/history','POST',{});await reload(true);if(t.dataset.historyConversation)await choose(Number(id));toast(`Đã thêm ${r.added} tin nhắn. ${r.more?'Bấm tiếp để tải phần cũ hơn.':'Đã tải hết phần lịch sử Facebook trả về cho lượt này.'}`);}finally{if(t.isConnected){t.disabled=false;t.textContent=old;}}}
 if(t.dataset.contentTab){contentType=t.dataset.contentTab;selected=null;messages=[];events=[];renderBody();$('#tab-'+contentType).focus();}
 if(t.dataset.deleteChannel){const c=state.channels.find(c=>c.id===Number(t.dataset.deleteChannel));confirmAction('Xoá kênh '+c.name,'Xoá kết nối, lịch sử hội thoại và phân quyền của kênh này khỏi Choibox. Không xoá Page/OA hoặc nội dung trên Facebook/Zalo. Không thể hoàn tác.','Xoá kênh',async()=>{await api('/channels/'+c.id,'DELETE',{confirm:true});channel='all';await reload(true);toast('Đã xoá kênh khỏi Choibox.');});}
 if(t.dataset.moderate){const action=t.dataset.moderate,id=Number(t.dataset.messageId),c=current(),info={'local-delete':['Xoá khỏi Choibox','Nội dung này sẽ bị xoá khỏi Choibox cho toàn đội ngũ. Tin gốc trên Facebook/Zalo vẫn giữ nguyên. Không thể hoàn tác.','Xoá khỏi Choibox'],delete:['Xoá bình luận Facebook','Bình luận này sẽ bị xoá trên Facebook. Thao tác không thể hoàn tác.','Xoá bình luận'],hide:['Ẩn bình luận Facebook','Ẩn bình luận trên Facebook. Người viết và một số người liên quan vẫn có thể thấy theo quy tắc Facebook. Có thể hiện lại sau.','Ẩn bình luận'],unhide:['Hiện bình luận Facebook','Bình luận sẽ hiển thị lại trên Facebook.','Hiện bình luận']}[action];confirmAction(...info,async()=>{await api('/messages/'+id+'/moderate','POST',{action,confirm:true});await choose(c.id);toast('Đã thực hiện thao tác.');});}
 if(t.dataset.view){if(modal.querySelector('.mobile-navigation'))modal.close();view=t.dataset.view;shell();}
 if(t.dataset.channel){if(modal.querySelector('.mobile-navigation'))modal.close();channel=t.dataset.channel;selected=null;view='inbox';shell();}
 if(t.dataset.filter){filter=t.dataset.filter;renderBody();}
 if(t.dataset.conv)await choose(Number(t.dataset.conv));
 if(t.dataset.compose){drafts.set(selected,$('#compose-text').value);note=t.dataset.compose==='note';$('#chat').innerHTML=chatHTML();scrollChat();}
 if(t.dataset.tagFilter!==undefined){tagFilter=t.dataset.tagFilter;refreshList();}if(t.dataset.removeTag)await patch({tags:current().tags.filter(x=>x!==t.dataset.removeTag)});
 if(t.dataset.recoverZalo){t.disabled=true;await api('/zalo-personal/channels/'+t.dataset.recoverZalo+'/sync','POST',{restart:t.dataset.recoveryRestart==='1'});await reload(true);}
 if(t.dataset.checkChannel){t.disabled=true;const r=await api('/channels/'+t.dataset.checkChannel+'/check','POST',{});toast(r.health);await reload(true);}
 if(t.dataset.toggleChannel){const c=state.channels.find(c=>c.id===Number(t.dataset.toggleChannel));await api('/channels/'+c.id,'PATCH',{enabled:!c.enabled});await reload(true);}
 if(t.dataset.credentials){const ch=state.channels.find(c=>c.id===Number(t.dataset.credentials));if(ch.provider==='facebook')await facebookStart();else if(ch.provider==='zalo_personal')await personalUI.start(ch.id);else channelForm(ch.id);}if(t.dataset.editUser)userForm(Number(t.dataset.editUser));
 const a=t.dataset.action;
 if(a==='navigation')show('Không gian làm việc',`<div class="mobile-navigation">${nav()}</div>`);
 if(a==='storage-retry')await loadStorage();
 if(a==='attach')$('#attachment-file').click();
 if(a==='remove-file'){const f=files.get(selected);if(f){await api('/attachments/'+f.id,'DELETE');files.delete(selected);}$('#chat').innerHTML=chatHTML();scrollChat();}
 if(a==='create-order')openOrder();
 if(a==='add-tag')openTag();
 if(t.dataset.tagColor)openTag(t.dataset.tagColor);
 if(a==='edit-profile')openProfile();
 if(a==='refresh-profile'){const c=current();t.disabled=true;t.textContent='Đang đồng bộ…';try{await api('/conversations/'+c.id+'/profile-refresh','POST',{});await reload();if(modal.open&&modal.querySelector('.modal-detail'))modal.querySelector('.modal-detail').innerHTML=detailHTML();}finally{if(t.isConnected){t.disabled=false;t.textContent='↻ Đồng bộ hồ sơ';}}}
 if(a==='export-connection'){const b=new Blob([JSON.stringify(loadAccess.cache.connection_file,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),link=document.createElement('a');link.href=url;link.download='choibox-connection.json';link.click();URL.revokeObjectURL(url);}
 if(a==='close-modal')modal.close();if(a==='refresh'){await reload(true);if(selected)await choose(selected);toast('Đã cập nhật hộp thư.');}
 if(a==='back'){const id=selected;selected=null;renderBody();document.querySelector('[data-conv="'+id+'"]')?.focus({preventScroll:true});}
 if(a==='logout'){await api('/logout','POST',{});user=null;csrf=null;await auth();}
 if(a==='demo'){await api('/demo','POST',{});await reload(true);toast('Đã tạo dữ liệu mẫu. Các tin trả lời mẫu không gửi ra nền tảng.');}
 if(a==='resolve')await patch({status:current().status==='closed'?'open':'closed'});
 if(a==='claim')await patch({assignee:user.id});if(a==='add-channel')await addChannel();if(a==='connect-facebook')await facebookStart();if(a==='facebook-setup')await facebookSetup();if(a==='connect-zalo')channelForm();if(a==='connect-zalo-personal')await personalUI.start(t.dataset.zaloReconnect?Number(t.dataset.zaloReconnect):undefined);if(a==='add-user')userForm();
 if(a==='add-reply')show('Thêm câu trả lời mẫu',`<form class="form" data-form="reply">${field('Tên mẫu','title')}<label>Nội dung</label><textarea aria-label="Nội dung mẫu" name="body" rows="5" maxlength="2000" required></textarea><button class="primary">Lưu mẫu</button><p class="error"></p></form>`);
 if(a==='password')show('Đổi mật khẩu',`<form class="form" data-form="password">${field('Mật khẩu hiện tại','current','password')}${field('Mật khẩu mới','password','password')}<button class="primary">Đổi mật khẩu</button><p class="error"></p></form>`);
 if(a==='edit-conversation'){const c=current();show('Thông tin hội thoại',`<div class="detail">${detailHTML()}</div>`);const d=modal.querySelector('.detail');d.classList.add('modal-detail');}
 }catch(e){toast(e.message);if(t.isConnected)t.disabled=false;}});
// Detail controls inside the dialog use the same permissions and API as the main panel.
modal.addEventListener('change',async e=>{if(['assignee','status','priority'].includes(e.target.id)){try{await patch({[e.target.id]:e.target.id==='assignee'?(e.target.value?Number(e.target.value):null):e.target.value});modal.close();}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(f.dataset.form==='compose'&&sending)return;const d=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type=submit],button.primary');if(button)button.disabled=true;try{
 const action=f.dataset.form;
 if(action==='confirm-action'){if(!pendingConfirmation)throw Error('Thao tác đã hết hạn.');await pendingConfirmation();pendingConfirmation=null;modal.close();}
 if(action==='storage'){const body={days:Number(d.days),max_bytes:Number(d.max_mb)*1024**2};confirmAction('Lưu giới hạn bộ nhớ đệm','Thiết lập áp dụng cho toàn máy chủ. Tệp đến hạn hoặc vượt giới hạn sẽ bị dọn; tệp không có nguồn có thể không xem lại được. Tin nhắn chữ và đơn hàng vẫn giữ.','Lưu thiết lập',async()=>{await api('/storage','PATCH',body);await loadStorage();toast('Đã lưu thiết lập lưu trữ.');});}
 if(action==='setup'){await api('/setup','POST',d);await api('/login','POST',d);await start();}
 if(action==='login'){await api('/login','POST',d);await start();}
 if(action==='compose')await composeSend(f,d);
 if(action==='tag'){const c=current(),tag=d.tag.trim();if(!tag)throw Error('Nhập tên thẻ.');if(!c.tags.includes(tag))await patch({tags:[...c.tags,tag]});await api('/tags','POST',{name:tag,color:d.color});modal.close();await reload();}
 if(action==='order')await saveOrder(f,d);
 if(action==='profile'){await api('/conversations/'+f.dataset.conversation+'/profile','PATCH',d);modal.close();await reload();}
 if(action==='facebook-config'){await api('/facebook/config','POST',d);await facebookSetup();toast('Đã lưu cấu hình Facebook.');}
 if(action==='facebook-pages'){const ids=new FormData(f).getAll('page');if(!ids.length)throw Error('Chọn ít nhất một Page.');const result=await api('/facebook/flows/'+facebookFlow+'/connect','POST',{page_ids:ids});await reload(true);const failed=result.results.filter(p=>!p.ok);if(failed.length){formError(f,new Error(failed.map(p=>p.name+': '+p.error).join(' ')));}else{modal.close();toast('Đã kết nối '+result.results.length+' Page.');}}
 if(action==='channel'){const id=f.dataset.id;await api(id?'/channels/'+id+'/credentials':'/channels','POST',d);modal.close();await reload(true);toast('Đã lưu. Kiểm tra token rồi đăng ký webhook trên nền tảng.');}
 if(action==='user'){let id=f.dataset.id;if(!id){const r=await api('/users','POST',d);id=r.id;}const grants=state.channels.filter(c=>d['grant-'+c.id]==='on').map(c=>({channel_id:c.id,can_reply:d['reply-'+c.id]==='1'}));await api('/users/'+id,'PATCH',{role:d.role,active:d.active===undefined?true:d.active==='1',...(f.dataset.id&&d.password?{password:d.password}:{}),grants});modal.close();await reload(true);toast('Đã lưu tài khoản và quyền truy cập.');}
 if(action==='reply'){await api('/replies','POST',d);modal.close();await reload(true);toast('Đã lưu câu trả lời mẫu.');}
 if(action==='password'){await api('/password','POST',d);modal.close();toast('Đã đổi mật khẩu.');}
 }catch(err){formError(f,err);}finally{sending=false;if(button?.isConnected)button.disabled=false;const send=$('.composer .primary');if(send&&canReply(current()))send.disabled=false;const attach=$('[data-action="attach"]');if(attach)attach.disabled=note||uploading;}});
const {storageHTML,icon,customerAvatar,customerProfile,tagChip,tagColor,attachmentHTML,filePreview,orderSummary,orderCard,ordersPage,openTag,openProfile,openOrder,saveOrder,composeSend}=workspaceUI({esc,api,show,toast,$,modal,initials,read:()=>({state,current:current(),files,drafts,csrf,note,sending,uploading}),setSending:v=>{sending=v;const b=$('[data-action="attach"]');if(b)b.disabled=v||note||uploading;},setUploading:v=>{uploading=v;const b=$('[data-action="attach"]');if(b)b.disabled=v;},choose,reload,refreshComposer:()=>{$('#chat').innerHTML=chatHTML();scrollChat();},refreshMessages:()=>{if($('#messages'))$('#messages').innerHTML=messagesHTML();},openChat:async id=>{view='inbox';const c=state.conversations.find(c=>c.id===id);if(c)contentType=c.kind||'chat';shell();await choose(id);}});
async function start(){const me=await api('/me');user=me.user;csrf=me.csrf;await reload(true);}
setInterval(async()=>{if(!user||polling||document.hidden||modal.open||sending)return;polling=true;try{const next=await api('/state');if(JSON.stringify(next)!==stamp){state=next;stamp=JSON.stringify(next);if(view==='orders'||view==='channels')renderBody();if(selected&&!current()){selected=null;messages=[];shell();}else if(view==='inbox'){refreshList();if(document.activeElement?.tagName!=='SELECT')$('#detail').innerHTML=detailHTML();refreshCustomerHeader();}}if(selected&&view==='inbox'){const id=selected,ms=await api(`/conversations/${id}/messages`);if(id===selected&&JSON.stringify(ms)!==chatStamp&&!document.querySelector('.message-menu[open]')){messages=ms;chatStamp=JSON.stringify(ms);const el=$('#messages'),bottom=el&&el.scrollHeight-el.scrollTop-el.clientHeight<80;if(el){el.innerHTML=messagesHTML();if(bottom)scrollChat();}}}}catch(e){if(user)toast('Không cập nhật được dữ liệu. Kiểm tra ứng dụng đang chạy.');}finally{polling=false;}},4000);
const personalUI=zaloPersonalUI({api,show,modal,esc,reload,toast});
try{await start();}catch{await auth();}

function resizeMobile(){if(window.innerWidth<=780)document.documentElement.style.setProperty("--app-height",(window.visualViewport?.height||window.innerHeight)+"px");else document.documentElement.style.removeProperty("--app-height");}window.visualViewport?.addEventListener("resize",resizeMobile);window.addEventListener("resize",resizeMobile);resizeMobile();
